class Solution { private fun same(first:Array<IntArray>,second:Array<IntArray>):Boolean=first.indices.all{first[it].contentEquals(second[it])};private fun rotate(matrix:Array<IntArray>):Array<IntArray>{val n=matrix.size;val result=Array(n){IntArray(n)};for(row in 0 until n)for(col in 0 until n)result[col][n-1-row]=matrix[row][col];return result};fun findRotation(mat:Array<IntArray>,target:Array<IntArray>):Boolean{var current=mat;repeat(4){if(same(current,target))return true;current=rotate(current)};return false} }
